<?php
namespace Tests\Feature;
use App\Models\{BookingCuci,KendaraanPelanggan,PaketCuci,User};
use App\Services\BookingCuciService;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
class BookingCuciStage4DTest extends TestCase
{
 use DatabaseTransactions;
 private function user(string $role):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$role))->firstOrFail();}
 private function otherCustomer(User $u):User{return User::whereHas('role',fn($q)=>$q->where('nama_role','pelanggan'))->where('id_user','<>',$u->id_user)->firstOrFail();}
 private function vehicle(User $u,string $status='aktif'):KendaraanPelanggan{return $u->pelanggan->kendaraan()->create(['merk'=>'QA','model'=>'Wash Vehicle','nomor_polisi'=>'CW-'.random_int(1000,9999),'status'=>$status]);}
 private function valid(User $u):array{return [$u,$this->vehicle($u),PaketCuci::where('status','aktif')->firstOrFail()];}
 public function test_baseline_import_is_present():void{$this->assertSame(1,BookingCuci::count());$this->assertDatabaseHas('booking_cuci',['id_booking_cuci'=>1,'kode_booking'=>'BCW-202609-067D478B','status'=>'selesai']);}
 public function test_customer_can_create_booking_with_server_price_snapshot():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$b=app(BookingCuciService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00','QA');$this->assertSame('menunggu',$b->status);$this->assertSame((string)$p->harga,(string)$b->harga);$this->assertStringStartsWith('BCW-',$b->kode_booking);}
 public function test_guest_and_customer_cannot_access_operations():void{$this->get('/pelanggan/booking-cuci')->assertRedirect('/login');$this->actingAs($this->user('pelanggan'))->get('/petugas/booking-cuci')->assertForbidden();}
 public function test_vehicle_ownership_is_enforced():void{$a=$this->user('pelanggan');$b=$this->otherCustomer($a);$v=$this->vehicle($b);$p=PaketCuci::where('status','aktif')->firstOrFail();$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(BookingCuciService::class)->create($a->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);}
 public function test_inactive_vehicle_and_package_are_blocked():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$v->update(['status'=>'nonaktif']);$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(BookingCuciService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);}
 public function test_inactive_package_is_blocked():void{$u=$this->user('pelanggan');$v=$this->vehicle($u);$p=PaketCuci::where('status','aktif')->firstOrFail();$p->update(['status'=>'nonaktif']);$this->expectException(\Illuminate\Database\Eloquent\ModelNotFoundException::class);app(BookingCuciService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);}
 public function test_past_date_is_blocked():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$this->expectException(\RuntimeException::class);app(BookingCuciService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->subDay()->toDateString(),'10:00',null);}
 public function test_price_status_and_customer_tampering_are_ignored():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$this->withoutMiddleware()->actingAs($u)->post('/pelanggan/booking-cuci',['id_kendaraan_pelanggan'=>$v->id_kendaraan_pelanggan,'id_paket'=>$p->id_paket,'tanggal'=>now()->addDay()->toDateString(),'jam'=>'10:00','harga'=>1,'status'=>'selesai','id_pelanggan'=>999])->assertRedirect();$b=BookingCuci::latest('id_booking_cuci')->first();$this->assertSame('menunggu',$b->status);$this->assertSame((string)$p->harga,(string)$b->harga);$this->assertSame($u->pelanggan->id_pelanggan,$b->id_pelanggan);}
 public function test_admin_and_petugas_can_confirm_and_assign_petugas():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$b=app(BookingCuciService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);$this->actingAs($this->user('petugas'))->post('/petugas/booking-cuci/'.$b->id_booking_cuci.'/confirm')->assertRedirect();$this->assertSame('diterima',$b->fresh()->status);$this->assertNotNull($b->fresh()->id_petugas);}
 public function test_start_transition_moves_to_process():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$svc=app(BookingCuciService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);$svc->confirm($b->id_booking_cuci,1);$svc->start($b->id_booking_cuci,1);$this->assertSame('proses',$b->fresh()->status);}
 public function test_customer_can_cancel_waiting_and_accepted():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$svc=app(BookingCuciService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);$svc->cancel($b->id_booking_cuci,$u->pelanggan->id_pelanggan);$this->assertSame('dibatalkan',$b->fresh()->status);}
 public function test_customer_cannot_cancel_process_or_other_booking():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$svc=app(BookingCuciService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);$svc->confirm($b->id_booking_cuci,1);$svc->start($b->id_booking_cuci,1);$this->expectException(\RuntimeException::class);$svc->cancel($b->id_booking_cuci,$u->pelanggan->id_pelanggan);}
 public function test_customer_cannot_view_other_booking():void{$a=$this->user('pelanggan');$b=$this->otherCustomer($a);$v=$this->vehicle($b);$p=PaketCuci::where('status','aktif')->firstOrFail();$booking=app(BookingCuciService::class)->create($b->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);$this->actingAs($a)->get('/pelanggan/booking-cuci/'.$booking->id_booking_cuci)->assertForbidden();}
 public function test_invalid_transition_is_blocked():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$svc=app(BookingCuciService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);$svc->confirm($b->id_booking_cuci,1);$this->expectException(\RuntimeException::class);$svc->confirm($b->id_booking_cuci,1);}
 public function test_concurrent_like_start_and_cancel_is_consistent():void{[$u,$v,$p]=$this->valid($this->user('pelanggan'));$svc=app(BookingCuciService::class);$b=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);$svc->confirm($b->id_booking_cuci,1);$svc->start($b->id_booking_cuci,1);$this->assertSame('proses',$b->fresh()->status);$this->expectException(\RuntimeException::class);$svc->cancel($b->id_booking_cuci,$u->pelanggan->id_pelanggan);}
 public function test_no_notification_is_created_when_native_has_none():void{$before=\App\Models\Notifikasi::count();[$u,$v,$p]=$this->valid($this->user('pelanggan'));app(BookingCuciService::class)->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,$p->id_paket,now()->addDay()->toDateString(),'10:00',null);$this->assertSame($before,\App\Models\Notifikasi::count());}
 public function test_regression_previous_modules_remain_available():void{$this->get('/login')->assertOk();$this->get('/mobil')->assertOk();$this->actingAs($this->user('admin'))->get('/admin/paket-cuci')->assertOk();$this->actingAs($this->user('admin'))->get('/admin/inventory/stok')->assertOk();}
}
